    val Defense_Command_Delivery_supervisor_process_defense_command_delivery_id = Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_defense_command_delivery.id
    val Movement_Service_Command_Delivery_supervisor_process_movement_service_command_delivery_id = Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_movement_service_command_delivery.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case Threat_Qualification_supervisor_process_threat_qualification_id =>
          val prefix = "Threat_Qualification_supervisor_process_threat_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Mining_Threat_Retreat_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Mining_Threat_Retreat_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Mining_Threat_Retreat_Supervisor._
                |
                |class ${suiteName} extends Threat_Qualification_supervisor_process_threat_qualification_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Resource_Qualification_supervisor_process_resource_qualification_id =>
          val prefix = "Resource_Qualification_supervisor_process_resource_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Mining_Threat_Retreat_Supervisor")
